from fractions import Fraction

def f(x, n):
    return sum(Fraction(r,1)/Fraction(x) for r in range(1, n+1)) if False else sum(r/(x-r) for r in range(1, n+1))

def count_roots(n):
    # scan intervals between poles, use bisection on each (r, r+1) plus outer intervals
    import math
    roots = []
    def bisect(a, b):
        fa, fb = f(a, n), f(b, n)
        for _ in range(200):
            m = (a+b)/2
            fm = f(m, n)
            if fa*fm <= 0:
                b, fb = m, fm
            else:
                a, fa = m, fm
        return (a+b)/2
    # inner intervals
    for r in range(1, n):
        a = r + 1e-9
        b = (r+1) - 1e-9
        fa, fb = f(a, n), f(b, n)
        if fa > 0 > fb:
            roots.append(bisect(a, b))
    # outer intervals
    a = -1e9; b = 1 - 1e-9
    if f(a, n)*f(b, n) < 0:
        roots.append(bisect(a, b))
    a = n + 1e-9; b = 1e9
    if f(a, n)*f(b, n) < 0:
        roots.append(bisect(a, b))
    return roots

for n in [1, 2, 3, 4, 5]:
    rs = count_roots(n)
    print(n, len(rs), [round(x, 6) for x in rs])
